def camel_to_snake(name: str) -> str:
    if not name:
        return name

    parts = []
    for char in name:
        if char.isupper():
            if parts and parts[-1].islower():
                parts.append('_')
            parts.append(char.lower())
        else:
            parts.append(char)

    return ''.join(parts)

def run_length_encode(s: str) -> str:
    if not s:
        return ""

    encoded = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            encoded.append(str(count))
            encoded.append(s[i - 1])
            count = 1

    # Add the last run to the encoded list
    encoded.append(str(count))
    encoded.append(s[-1])

    return ''.join(encoded)

