def run_length_decode(s: str) -> str:
    if not s:
        return ""

    decoded = []
    i = 0

    while i < len(s):
        count = ''
        while i < len(s) and s[i].isdigit():
            count += s[i]
            i += 1
        if not count:  # No digit found, treat as a single character
            decoded.append(s[i])
            i += 1
        else:
            decoded.extend([s[i]] * int(count))
            i += len(count)

    return ''.join(decoded)

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    if not intervals:
        return []

    # Sort intervals by their start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for interval in intervals[1:]:
        current_end = merged[-1][1]

        # If the current interval overlaps with the last merged interval, merge them
        if interval[0] <= current_end:
            merged[-1][1] = max(interval[1], current_end)
        else:
            # Otherwise, add the current interval to the merged list
            merged.append(interval)

    return merged

def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
