def expand_ranges(s: str) -> list[int]:
    if not s:
        return []

    def parse_range(part):
        start, end = map(int, part.split('-'))
        if start > end:
            raise ValueError(f"Invalid range: {part}")
        return range(start, end + 1)

    parts = s.split(',')
    expanded = set()

    for part in parts:
        try:
            expanded.update(parse_range(part))
        except ValueError as e:
            print(f"Error parsing part '{part}': {e}")

    return sorted(expanded)

def missing_ranges(nums: list[int], lo: int, hi: int) -> list[list[int]]:
    result = []
    if not nums:
        return [[lo, hi]] if lo <= hi else []

    # Handle the start of the range
    if nums[0] > lo:
        result.append([lo, nums[0] - 1])

    for i in range(1, len(nums)):
        if nums[i] - nums[i-1] == 2:
            result.append([nums[i-1]+1, nums[i]-1])
        elif nums[i] - nums[i-1] > 2:
            result.append([nums[i-1]+1, nums[i]-2])

    # Handle the end of the range
    if nums[-1] < hi:
        result.append([nums[-1]+1, hi])

    return result

def missing_ranges(nums: list[int], lo: int, hi: int) -> list[list[int]]:
    if not nums or nums[0] > lo:
        yield [lo, lo]

    for i in range(len(nums)):
        if i == 0:
            start = nums[i]
        else:
            start = min(nums[i], nums[i-1])

        end = max(nums[i], nums[i-1])

        if start < end - 1:
            yield [start, end-1]

    if nums[-1] < hi:
        yield [nums[-1]+1, hi]
